class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.spy_closes = deque(maxlen=2)
        self.spy_sma_values = deque(maxlen=2)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # The extra bar is needed to compare both today's and yesterday's
        # close-to-SMA relationship.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(float(data.Bars[spy].Close))
            if self.spy_sma.IsReady:
                self.spy_sma_values.append(float(self.spy_sma.Current.Value))

        if data.Bars.ContainsKey(aapl):
            aapl_close = float(data.Bars[aapl].Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or len(self.spy_closes) < 2
            or len(self.spy_sma_values) < 2
        ):
            return

        # Reconcile the private lots with fills and corporate-action share
        # adjustments before applying today's rules.
        if self.strategy_a_shares:
            self.strategy_a_shares = max(0, int(self.Portfolio[spy].Quantity))
        if self.strategy_b_shares:
            self.strategy_b_shares = max(0, int(self.Portfolio[aapl].Quantity))

        spy_crossed_below = (
            self.spy_closes[0] >= self.spy_sma_values[0]
            and self.spy_closes[1] < self.spy_sma_values[1]
        )
        spy_crossed_above = (
            self.spy_closes[0] <= self.spy_sma_values[0]
            and self.spy_closes[1] > self.spy_sma_values[1]
        )

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / float(data.Bars[aapl].Close))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_shares = quantity

