class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = deque(maxlen=101)
        self.spy_previous_above_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # The extra observation makes both today's and yesterday's 100-day
        # moving-average relationships available for the first possible cross.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if bars.ContainsKey(spy):
            self.spy_closes.append(float(bars[spy].Close))

        if bars.ContainsKey(aapl):
            aapl_close = float(bars[aapl].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close

        spy_above_sma = None
        if len(self.spy_closes) >= 100:
            spy_close = self.spy_closes[-1]
            spy_sma = sum(list(self.spy_closes)[-100:]) / 100.0
            spy_above_sma = spy_close > spy_sma

        all_bars_present = all(
            bars.ContainsKey(self.symbols[ticker]) for ticker in self.tickers
        )
        indicators_ready = (
            len(self.spy_closes) == 101
            and self.spy_previous_above_sma is not None
            and self.aapl_previous_close is not None
            and self.aapl_rsi.IsReady
        )

        if all_bars_present and indicators_ready and not self.IsWarmingUp:
            self._evaluate_strategy_a(bars[spy], spy_above_sma)
            self._evaluate_strategy_b(bars[aapl])

        # Cross state is market state, so it advances even when another ticker's
        # bar is absent and trading rules are skipped.
        if spy_above_sma is not None:
            self.spy_previous_above_sma = spy_above_sma

    def _evaluate_strategy_a(self, spy_bar, spy_above_sma):
        crossed_above = (
            not self.spy_previous_above_sma and spy_above_sma
        )
        crossed_below = (
            self.spy_previous_above_sma and not spy_above_sma
        )

        # Sells are evaluated before buys, and only the applicable side of this
        # strategy's private lot is considered.
        if self.strategy_a_shares > 0:
            if crossed_below:
                self.MarketOrder(
                    self.symbols["SPY"], -self.strategy_a_shares,
                    tag="Strategy A sell"
                )
                self.strategy_a_shares = 0
            return

        if crossed_above:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(
                    self.symbols["SPY"], quantity, tag="Strategy A buy"
                )
                self.strategy_a_shares = quantity

    def _evaluate_strategy_b(self, aapl_bar):
        if self.strategy_b_shares > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(
                    self.symbols["AAPL"], -self.strategy_b_shares,
                    tag="Strategy B sell"
                )
                self.strategy_b_shares = 0
            return

        if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
            quantity = floor(20_000 / float(aapl_bar.Close))
            if quantity > 0:
                self.MarketOrder(
                    self.symbols["AAPL"], quantity, tag="Strategy B buy"
                )
                self.strategy_b_shares = quantity

