        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.Add(float(data.Bars[spy].Close))
        if data.Bars.ContainsKey(aapl):
            self.aapl_closes.Add(float(data.Bars[aapl].Close))

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp:
            return
        if not self.spy_closes.IsReady or not self.aapl_closes.IsReady:
            return
        if not self.aapl_rsi.IsReady:
            return

        self._run_spy_strategy()
        self._run_aapl_strategy()

    def _run_spy_strategy(self):
        symbol = self.symbols["SPY"]
        today_close = self.spy_closes[0]
        yesterday_close = self.spy_closes[1]
        today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma
        if self.spy_lot > 0 and crossed_below:
            self.MarketOrder(symbol, -self.spy_lot)
            self.spy_lot = 0

        crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma
        if self.spy_lot == 0 and crossed_above:
            quantity = self.CalculateOrderQuantity(symbol, 0.40)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self):
        symbol = self.symbols["AAPL"]

        if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(symbol, -self.aapl_lot)
            self.aapl_lot = 0

        red_for_three_days = all(
            self.aapl_closes[i] < self.aapl_closes[i + 1] for i in range(3)
        )
        if self.aapl_lot == 0 and red_for_three_days:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest // self.aapl_closes[0])
                if quantity > 0:
                    self.MarketOrder(symbol, quantity)
                    self.aapl_lot = quantity

