    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_closes.add(float(spy_bar.close))

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        if len(bars) != len(self.symbols):
            return

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and self._spy_crossed_below_sma():
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.is_ready:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0 and self._spy_crossed_above_sma():
            close = float(spy_bar.close)
            quantity = int((0.40 * float(self.portfolio.total_portfolio_value)) // close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_amount = 20_000.0
            if float(self.portfolio.cash) >= cash_amount:
                quantity = int(cash_amount // float(aapl_bar.close))
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_crossed_above_sma(self):
        if not self.spy_closes.is_ready:
            return False
        today_close = float(self.spy_closes[0])
        yesterday_close = float(self.spy_closes[1])
        today_sma = sum(float(self.spy_closes[i]) for i in range(100)) / 100.0
        yesterday_sma = sum(float(self.spy_closes[i]) for i in range(1, 101)) / 100.0
        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _spy_crossed_below_sma(self):
        if not self.spy_closes.is_ready:
            return False
        today_close = float(self.spy_closes[0])
        yesterday_close = float(self.spy_closes[1])
        today_sma = sum(float(self.spy_closes[i]) for i in range(100)) / 100.0
        yesterday_sma = sum(float(self.spy_closes[i]) for i in range(1, 101)) / 100.0
        return yesterday_close >= yesterday_sma and today_close < today_sma

