class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        self.closes = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol
            self.closes[symbol] = deque(maxlen=101)

        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                bars[ticker] = bar
                self.closes[symbol].append(Decimal(str(bar.Close)))

        if len(bars) != len(self.tickers):
            return

        self._run_spy_strategy(bars["SPY"])
        self._run_aapl_strategy(bars["AAPL"])

    def _run_spy_strategy(self, bar):
        symbol = self.symbols["SPY"]
        history = self.closes[symbol]
        if len(history) < 101:
            return

        values = list(history)
        yesterday_close = values[-2]
        today_close = values[-1]
        yesterday_sma = sum(values[-101:-1]) / Decimal(100)
        today_sma = sum(values[-100:]) / Decimal(100)
        crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma
        crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma

        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(symbol, -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = self.CalculateOrderQuantity(symbol, 0.40)
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, bar):
        symbol = self.symbols["AAPL"]
        history = self.closes[symbol]
        if len(history) < 4 or not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.Current.Value > Decimal(60):
                self.MarketOrder(symbol, -self.aapl_lot)
                self.aapl_lot = 0
            return

        values = list(history)
        red_for_three_days = (
            values[-3] < values[-4]
            and values[-2] < values[-3]
            and values[-1] < values[-2]
        )
        cash_to_invest = Decimal(20000)
        available_cash = Decimal(str(self.Portfolio.Cash))
        close = Decimal(str(bar.Close))
        if red_for_three_days and available_cash >= cash_to_invest:
            quantity = int(math.floor(cash_to_invest / close))
            if quantity > 0:
                self.MarketOrder(symbol, quantity)
                self.aapl_lot = quantity

