class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # Two complete 100-day SMA values require 101 closes.
        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.last_processed_date = None

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Keep quantities belonging to the private lots correct across splits.
        if spy in data.Splits and data.Splits[spy].Type == SplitType.SplitOccurred:
            self.spy_lot = int(round(self.spy_lot / data.Splits[spy].SplitFactor))
        if aapl in data.Splits and data.Splits[aapl].Type == SplitType.SplitOccurred:
            self.aapl_lot = int(round(self.aapl_lot / data.Splits[aapl].SplitFactor))

        bars = data.Bars
        if spy in bars:
            self.spy_closes.append(float(bars[spy].Close))
        if aapl in bars:
            aapl_close = float(bars[aapl].Close)
            self.aapl_closes.append(aapl_close)
            self.aapl_rsi.Update(bars[aapl].EndTime, aapl_close)

        # A daily slice can contain auxiliary data without a new daily bar.
        bar_date = bars[spy].EndTime.date() if spy in bars else None
        if bar_date is not None and bar_date == self.last_processed_date:
            return

        # The system is evaluated only when all five of today's bars are present.
        if any(symbol not in bars for symbol in self.symbols.values()):
            return
        self.last_processed_date = bar_date

        # Strategy A: sells are evaluated before buys.
        if len(self.spy_closes) == 101:
            yesterday_close = self.spy_closes[-2]
            today_close = self.spy_closes[-1]
            yesterday_sma = sum(list(self.spy_closes)[:100]) / 100.0
            today_sma = sum(list(self.spy_closes)[1:]) / 100.0

            crosses_below = yesterday_close >= yesterday_sma and today_close < today_sma
            crosses_above = yesterday_close <= yesterday_sma and today_close > today_sma

            if self.spy_lot > 0 and crosses_below:
                self.MarketOrder(spy, -self.spy_lot)
                self.spy_lot = 0
            elif self.spy_lot == 0 and crosses_above:
                quantity = int(floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / today_close))
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.spy_lot = quantity

        # Strategy B: its sell is checked first, and its buy only while flat.
        if self.aapl_lot > 0:
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(aapl, -self.aapl_lot)
                self.aapl_lot = 0
        elif len(self.aapl_closes) == 4 and self.aapl_rsi.IsReady:
            red_for_three_days = all(
                self.aapl_closes[i] < self.aapl_closes[i - 1]
                for i in range(1, 4)
            )
            if red_for_three_days and float(self.Portfolio.Cash) >= 20_000.0:
                quantity = int(floor(20_000.0 / self.aapl_closes[-1]))
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

