class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_previous_relation = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_crossed_above = False
        spy_crossed_below = False
        if data.bars.contains_key(spy):
            spy_bar = data.bars[spy]
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)
            if self.spy_sma.is_ready:
                relation = spy_bar.close - self.spy_sma.current.value
                if self.spy_previous_relation is not None:
                    spy_crossed_above = (
                        self.spy_previous_relation <= 0 and relation > 0
                    )
                    spy_crossed_below = (
                        self.spy_previous_relation >= 0 and relation < 0
                    )
                self.spy_previous_relation = relation

        if data.bars.contains_key(aapl):
            aapl_bar = data.bars[aapl]
            if self.aapl_previous_close is not None:
                if aapl_bar.close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_bar.close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        # Each strategy's sell is evaluated before its buy. Pending orders keep
        # that private lot from issuing a second order before its fill arrives.
        if self.spy_lot > 0:
            if spy_crossed_below and not self.spy_order_pending:
                self.spy_order_pending = True
                self.market_order(spy, -self.spy_lot, tag="Strategy A sell")
        elif (
            not self.spy_order_pending
            and self.spy_sma.is_ready
            and spy_crossed_above
        ):
            quantity = self.calculate_order_quantity(spy, 0.40)
            if quantity > 0:
                self.spy_order_pending = True
                self.market_order(spy, quantity, tag="Strategy A buy")

        if self.aapl_lot > 0:
            if (
                self.aapl_rsi.is_ready
                and self.aapl_rsi.current.value > 60
                and not self.aapl_order_pending
            ):
                self.aapl_order_pending = True
                self.market_order(aapl, -self.aapl_lot, tag="Strategy B sell")
        elif (
            not self.aapl_order_pending
            and self.aapl_rsi.is_ready
            and self.aapl_red_streak >= 3
        ):
            cash = self.portfolio.cash_book["USD"].amount
            if cash >= 20_000:
                quantity = int(20_000 // data.bars[aapl].close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.market_order(aapl, quantity, tag="Strategy B buy")

    def on_order_event(self, order_event: OrderEvent):
        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        if order.tag.startswith("Strategy A"):
            if order_event.fill_quantity != 0:
                self.spy_lot += order_event.fill_quantity
            if order_event.status in [OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.spy_order_pending = False
        elif order.tag.startswith("Strategy B"):
            if order_event.fill_quantity != 0:
                self.aapl_lot += order_event.fill_quantity
            if order_event.status in [OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.aapl_order_pending = False

