class ParallelSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.add_equity(ticker, Resolution.DAILY)

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def on_data(self, data: Slice):
        bars = data.bars

        if bars.contains_key("SPY"):
            self.spy_closes.append(float(bars["SPY"].close))

        if bars.contains_key("AAPL"):
            aapl_close = float(bars["AAPL"].close)
            if self.aapl_previous_close is not None:
                change = aapl_close - self.aapl_previous_close
                self.aapl_red_streak = (
                    self.aapl_red_streak + 1 if change < 0 else 0
                )
                self._update_aapl_rsi(change)
            self.aapl_previous_close = aapl_close

        if any(not bars.contains_key(ticker) for ticker in self.tickers):
            return

        spy_cross_above = False
        spy_cross_below = False
        if len(self.spy_closes) == 101:
            closes = list(self.spy_closes)
            yesterday_sma = sum(closes[:100]) / 100
            today_sma = sum(closes[1:]) / 100
            spy_cross_above = (
                closes[-2] <= yesterday_sma and closes[-1] > today_sma
            )
            spy_cross_below = (
                closes[-2] >= yesterday_sma and closes[-1] < today_sma
            )

        # All sell rules are evaluated before either strategy's buy rule.
        if self.spy_lot > 0 and not self.spy_order_pending and spy_cross_below:
            self.spy_order_pending = True
            self.market_order("SPY", -self.spy_lot, tag="strategy-a-sell")

        if (
            self.aapl_lot > 0
            and not self.aapl_order_pending
            and self.aapl_rsi is not None
            and self.aapl_rsi > 60
        ):
            self.aapl_order_pending = True
            self.market_order("AAPL", -self.aapl_lot, tag="strategy-b-sell")

        if (
            self.spy_lot == 0
            and not self.spy_order_pending
            and spy_cross_above
        ):
            quantity = self.calculate_order_quantity("SPY", 0.40)
            if quantity > 0:
                self.spy_order_pending = True
                self.market_order("SPY", quantity, tag="strategy-a-buy")

        if (
            self.aapl_lot == 0
            and not self.aapl_order_pending
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= 20_000
        ):
            quantity = floor(20_000 / float(bars["AAPL"].close))
            if quantity > 0:
                self.aapl_order_pending = True
                self.market_order("AAPL", quantity, tag="strategy-b-buy")

    def _update_aapl_rsi(self, change):
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            self.rsi_seed_gains.append(gain)
            self.rsi_seed_losses.append(loss)
            if len(self.rsi_seed_gains) == self.rsi_period:
                self.rsi_average_gain = sum(self.rsi_seed_gains) / self.rsi_period
                self.rsi_average_loss = sum(self.rsi_seed_losses) / self.rsi_period
        else:
            self.rsi_average_gain = (
                self.rsi_average_gain * (self.rsi_period - 1) + gain
            ) / self.rsi_period
            self.rsi_average_loss = (
                self.rsi_average_loss * (self.rsi_period - 1) + loss
            ) / self.rsi_period

        if self.rsi_average_gain is not None:
            if self.rsi_average_loss == 0:
                self.aapl_rsi = 100.0
            else:
                relative_strength = self.rsi_average_gain / self.rsi_average_loss
                self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in [OrderStatus.FILLED, OrderStatus.CANCELED,
                                      OrderStatus.INVALID]:
            return

        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        if order_event.status == OrderStatus.FILLED:
            if order.tag == "strategy-a-buy":
                self.spy_lot += order_event.fill_quantity
            elif order.tag == "strategy-a-sell":
                self.spy_lot += order_event.fill_quantity
            elif order.tag == "strategy-b-buy":
                self.aapl_lot += order_event.fill_quantity
            elif order.tag == "strategy-b-sell":
                self.aapl_lot += order_event.fill_quantity

        if order.tag.startswith("strategy-a-"):
            self.spy_order_pending = False
        elif order.tag.startswith("strategy-b-"):
            self.aapl_order_pending = False

