class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.Daily).symbol
            for ticker in self.tickers
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.previous_close = {}
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        # This preserves enough pre-start daily observations for both sides of
        # the first possible 100-day-SMA crossing.
        self.set_warm_up(101, Resolution.Daily)

    def on_data(self, data: Slice):
        bars = {
            ticker: data.bars[symbol] if data.bars.contains_key(symbol) else None
            for ticker, symbol in self.symbols.items()
        }

        spy_bar = bars["SPY"]
        if spy_bar is not None:
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

        aapl_bar = bars["AAPL"]
        if aapl_bar is not None:
            old_aapl_close = self.previous_close.get("AAPL")
            if old_aapl_close is not None:
                if aapl_bar.close < old_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        all_bars_present = all(bar is not None for bar in bars.values())

        if (
            all_bars_present
            and not self.is_warming_up
            and self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
        ):
            self._evaluate_sells(spy_bar, aapl_bar)
            self._evaluate_buys(spy_bar, aapl_bar)

        if spy_bar is not None and self.spy_sma.is_ready:
            self.previous_spy_close = spy_bar.close
            self.previous_spy_sma = self.spy_sma.current.value

        for ticker, bar in bars.items():
            if bar is not None:
                self.previous_close[ticker] = bar.close

    def _evaluate_sells(self, spy_bar, aapl_bar):
        if self.spy_lot > 0 and self._spy_crosses_below_sma(spy_bar.close):
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

    def _evaluate_buys(self, spy_bar, aapl_bar):
        if self.spy_lot == 0 and self._spy_crosses_above_sma(spy_bar.close):
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = floor(20_000 / aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_crosses_above_sma(self, current_close):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and current_close > self.spy_sma.current.value
        )

    def _spy_crosses_below_sma(self, current_close):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and current_close < self.spy_sma.current.value
        )

