class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=101)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.lots = {"A": 0, "B": 0}
        self.pending_orders = {}
        self.pending_strategies = set()

        # Supplies pre-start observations while still preventing trades during warm-up.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = data.bars

        spy = self.symbols["SPY"]
        if spy in bars:
            spy_close = float(bars[spy].close)
            self.spy_closes.append(spy_close)
            spy_sma = (
                sum(list(self.spy_closes)[-100:]) / 100.0
                if len(self.spy_closes) >= 100
                else None
            )
        else:
            spy_close = None
            spy_sma = None

        aapl = self.symbols["AAPL"]
        if aapl in bars:
            aapl_bar = bars[aapl]
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)
        else:
            aapl_close = None

        have_every_bar = all(symbol in bars for symbol in self.symbols.values())
        if have_every_bar and not self.is_warming_up:
            # Sells are evaluated before buys.
            if (
                self.lots["A"] > 0
                and "A" not in self.pending_strategies
                and self.spy_previous_close is not None
                and self.spy_previous_sma is not None
                and spy_sma is not None
                and self.spy_previous_close >= self.spy_previous_sma
                and spy_close < spy_sma
            ):
                self._submit("A", -self.lots["A"], "Strategy A sell")

            if (
                self.lots["B"] > 0
                and "B" not in self.pending_strategies
                and self.aapl_rsi.is_ready
                and self.aapl_rsi.current.value > 60
            ):
                self._submit("B", -self.lots["B"], "Strategy B sell")

            if (
                self.lots["A"] == 0
                and "A" not in self.pending_strategies
                and self.spy_previous_close is not None
                and self.spy_previous_sma is not None
                and spy_sma is not None
                and self.spy_previous_close <= self.spy_previous_sma
                and spy_close > spy_sma
            ):
                quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
                if quantity > 0:
                    self._submit("A", quantity, "Strategy A buy")

            if (
                self.lots["B"] == 0
                and "B" not in self.pending_strategies
                and self.aapl_previous_close is not None
                and self.aapl_rsi.is_ready
                and self.aapl_red_streak >= 3
                and float(self.portfolio.cash) >= 20_000
            ):
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self._submit("B", quantity, "Strategy B buy")

        if spy_close is not None:
            self.spy_previous_close = spy_close
            self.spy_previous_sma = spy_sma
        if aapl_close is not None:
            self.aapl_previous_close = aapl_close

    def _submit(self, strategy, quantity, tag):
        symbol = self.symbols["SPY" if strategy == "A" else "AAPL"]
        ticket = self.market_order(symbol, quantity, tag=tag)
        self.pending_orders[ticket.order_id] = strategy
        self.pending_strategies.add(strategy)

    def on_order_event(self, order_event: OrderEvent):
        strategy = self.pending_orders.get(order_event.order_id)
        if strategy is None:
            return

        if order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            self.lots[strategy] += int(order_event.fill_quantity)
            if self.lots[strategy] < 0:
                self.lots[strategy] = 0

        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            self.pending_orders.pop(order_event.order_id, None)
            self.pending_strategies.discard(strategy)

