class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_changes = 0
        self.aapl_rsi_average_gain = None
        self.aapl_rsi_average_loss = None
        self.aapl_rsi_initial_gains = 0.0
        self.aapl_rsi_initial_losses = 0.0
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            spy_sma = (
                sum(self.spy_closes) / 100.0
                if len(self.spy_closes) == 100
                else None
            )
        else:
            spy_close = None
            spy_sma = None

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            self._update_aapl_state(aapl_close)

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self._evaluate_spy(spy_close, spy_sma)
            self._evaluate_aapl(float(bars["AAPL"].Close))

        if "SPY" in bars:
            self.spy_previous_close = spy_close
            self.spy_previous_sma = spy_sma

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is not None:
            change = close - self.aapl_previous_close
            if change < 0:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            gain = max(change, 0.0)
            loss = max(-change, 0.0)
            self.aapl_rsi_changes += 1

            if self.aapl_rsi_changes <= 14:
                self.aapl_rsi_initial_gains += gain
                self.aapl_rsi_initial_losses += loss
                if self.aapl_rsi_changes == 14:
                    self.aapl_rsi_average_gain = self.aapl_rsi_initial_gains / 14.0
                    self.aapl_rsi_average_loss = self.aapl_rsi_initial_losses / 14.0
                    self.aapl_rsi = self._rsi_value()
            else:
                self.aapl_rsi_average_gain = (
                    self.aapl_rsi_average_gain * 13.0 + gain
                ) / 14.0
                self.aapl_rsi_average_loss = (
                    self.aapl_rsi_average_loss * 13.0 + loss
                ) / 14.0
                self.aapl_rsi = self._rsi_value()

        self.aapl_previous_close = close

    def _rsi_value(self):
        if self.aapl_rsi_average_loss == 0:
            return 100.0 if self.aapl_rsi_average_gain > 0 else 50.0
        relative_strength = (
            self.aapl_rsi_average_gain / self.aapl_rsi_average_loss
        )
        return 100.0 - 100.0 / (1.0 + relative_strength)

    def _evaluate_spy(self, close, sma):
        if self.spy_previous_sma is None or sma is None:
            return

        crossed_above = (
            self.spy_previous_close <= self.spy_previous_sma and close > sma
        )
        crossed_below = (
            self.spy_previous_close >= self.spy_previous_sma and close < sma
        )

        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif crossed_above:
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        if self.aapl_rsi is None:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = floor(cash_to_invest / close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

from AlgorithmImports import *
from decimal import Decimal
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_relation = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            spy_relation = None
            if self.spy_sma.IsReady:
                spy_relation = spy_bar.Close - self.spy_sma.Current.Value
        else:
            spy_bar = None
            spy_relation = None

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_bar.Close
        else:
            aapl_bar = None

        has_every_bar = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        all_history_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.aapl_previous_close is not None
        )

        if not self.IsWarmingUp and has_every_bar and all_history_ready:
            self._evaluate_strategy_a(spy_bar, spy_relation)
            self._evaluate_strategy_b(aapl_bar)

        if spy_relation is not None:
            self.spy_previous_relation = spy_relation

    def _evaluate_strategy_a(self, bar, relation):
        if relation is None or self.spy_previous_relation is None:
            return

        symbol = self.symbols["SPY"]
        if self.strategy_a_shares > 0:
            if self.spy_previous_relation >= 0 and relation < 0:
                self.MarketOrder(symbol, -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif self.spy_previous_relation <= 0 and relation > 0:
            target_value = self.Portfolio.TotalPortfolioValue * Decimal("0.40")
            shares = floor(target_value / bar.Close)
            if shares > 0:
                self.MarketOrder(symbol, shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, bar):
        symbol = self.symbols["AAPL"]
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(symbol, -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3:
            cash_to_invest = Decimal("20000")
            if self.Portfolio.Cash >= cash_to_invest:
                shares = floor(cash_to_invest / bar.Close)
                if shares > 0:
                    self.MarketOrder(symbol, shares)
                    self.strategy_b_shares = shares
